\begin{equation}
    \Delta \mathbf{W} = \frac{1}{2} (\Delta \mathbf{W}^1+\Delta \mathbf{W}^2) = \frac{1}{2} (\mathbf{U}^1 \mathbf{\Sigma}^1 \mathbf{V}^1 + \mathbf{U}^2 \mathbf{\Sigma}^2 \mathbf{V}^2)
\end{equation}

